<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>WastedToken Mint — Physical Challenge Coins</title>
  <style>
    :root {
      --bg0: #050608;
      --bg1: #0d1117;
      --panel: #13161f;
      --text: #c9cacc;
      --muted: #8b8f98;
      --accent: #45a29e;
      --accent2: #66fcf1;
    }
    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      background: radial-gradient(ellipse at 50% 0%, #1a1f2d 0%, var(--bg0) 60%);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      line-height: 1.6;
    }
    header {
      text-align: center;
      padding: 3.5rem 1rem 1rem;
    }
    h1 {
      margin: 0;
      font-size: clamp(2.2rem, 6vw, 3.8rem);
      letter-spacing: 0.22em;
      text-transform: uppercase;
      font-weight: 800;
      color: #f5f7ff;
      text-shadow: 0 0 30px rgba(102,252,241,0.18);
    }
    .tagline {
      margin-top: 0.5rem;
      color: var(--accent);
      letter-spacing: 0.18em;
      text-transform: uppercase;
      font-size: 0.85rem;
      font-weight: 700;
    }
    .hero {
      display: flex;
      justify-content: center;
      align-items: center;
      padding: 1rem 1rem 3rem;
    }
    .hero-inner {
      position: relative;
      border-radius: 50%;
      box-shadow: 0 0 80px rgba(0,0,0,0.6), inset 0 0 60px rgba(0,0,0,0.35);
    }
    #coin-hero {
      display: block;
      width: min(620px, 88vw);
      height: auto;
      border-radius: 50%;
    }
    section {
      max-width: 980px;
      margin: 0 auto;
      padding: 2rem 1.5rem;
    }
    h2 {
      font-size: 1.7rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      margin-bottom: 0.8rem;
      color: #fff;
      border-bottom: 1px solid #2a2f3c;
      padding-bottom: 0.5rem;
    }
    .about p { color: var(--muted); max-width: 720px; }
    .edition-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
      gap: 1.5rem;
      margin-top: 1.5rem;
    }
    .edition {
      background: linear-gradient(180deg, #171b26, #0f1218);
      border: 1px solid #252a36;
      border-radius: 1rem;
      padding: 1.1rem;
      text-align: center;
      position: relative;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }
    .edition:hover { transform: translateY(-4px); box-shadow: 0 18px 40px rgba(0,0,0,0.45); }
    .edition h3 {
      margin: 0 0 0.6rem;
      font-size: 1.15rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: #fff;
    }
    .edition-canvas {
      width: 100%;
      height: auto;
      border-radius: 0.5rem;
      background: #0a0c10;
    }
    .price {
      margin: 0.6rem 0;
      color: var(--accent2);
      font-weight: 700;
      font-size: 1.05rem;
    }
    .status {
      display: inline-block;
      margin: 0.6rem 0 0;
      padding: 0.35rem 0.9rem;
      border-radius: 0.35rem;
      font-weight: 800;
      font-size: 0.8rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }
    .edition[data-state="sold-out"] .status { background: rgba(217, 83, 79, 0.16); color: #ff7a75; border: 1px solid rgba(217,83,79,0.35); }
    .edition[data-state="coming-soon"] .status { background: rgba(149, 117, 205, 0.14); color: #b39ddb; border: 1px solid rgba(149,117,205,0.35); }
    .buy {
      margin-top: 0.7rem;
      padding: 0.65rem 1.3rem;
      background: var(--accent);
      color: #020408;
      border: none;
      border-radius: 0.45rem;
      font-weight: 800;
      letter-spacing: 0.04em;
      cursor: pointer;
      transition: background 0.15s ease, transform 0.1s ease;
    }
    .buy:hover { background: var(--accent2); transform: scale(1.03); }
    .cart {
      position: fixed;
      top: 1rem;
      right: 1rem;
      background: rgba(19,22,31,0.9);
      border: 1px solid #2a2f3c;
      padding: 0.5rem 0.9rem;
      border-radius: 2rem;
      font-weight: 700;
      color: var(--accent2);
      z-index: 100;
    }
    footer {
      text-align: center;
      padding: 3rem 1rem 4rem;
      color: var(--muted);
      font-size: 0.85rem;
    }
  </style>
</head>
<body>

  <div class="cart">Cart: <span id="cart-count">0</span></div>

  <header>
    <h1>WastedToken Mint</h1>
    <div class="tagline">Minted metal. Tangible proof.</div>
  </header>

  <section class="hero">
    <div class="hero-inner">
      <canvas id="coin-hero" width="420" height="420"></canvas>
    </div>
  </section>

  <section class="about">
    <h2>About the Mint</h2>
    <p>
      WastedToken Mint turns digital bragging rights into heirloom-grade metal. Each challenge coin is struck from hand-finished dies, numbered, and sealed with a reeded edge—the same signature you will find on the coins carried by collectors, guilds, and the occasional troll king. We do not do paper. We do not do placeholders. We mint proof.
    </p>
  </section>

  <section id="editions">
    <h2>Collection</h2>
    <div class="edition-grid">

      <div class="edition" data-edition="bronze" data-state="available">
        <h3>Bronze Edition</h3>
        <canvas class="edition-canvas" width="200" height="200"></canvas>
        <p class="price">$29</p>
        <button class="buy">Add to cart</button>
      </div>

      <div class="edition" data-edition="silver" data-state="available">
        <h3>Silver Edition</h3>
        <canvas class="edition-canvas" width="200" height="200"></canvas>
        <p class="price">$49</p>
        <button class="buy">Add to cart</button>
      </div>

      <div class="edition" data-edition="gold" data-state="sold-out">
        <h3>Gold Edition</h3>
        <canvas class="edition-canvas" width="200" height="200"></canvas>
        <p class="status">SOLD OUT</p>
      </div>

      <div class="edition" data-edition="black" data-state="coming-soon">
        <h3>Black Obsidian</h3>
        <canvas class="edition-canvas" width="200" height="200"></canvas>
        <p class="status">MINTING AUTUMN 2025</p>
      </div>

    </div>
  </section>

  <footer>
    &copy; WastedToken Mint. All coins rendered in-browser. No external assets.
  </footer>

<script>
(function(){
  "use strict";

  /* ---------- Helpers ---------- */
  function drawArcText(ctx, text, radius, centerAngle, clockwise, font, color) {
    ctx.save();
    ctx.font = font;
    ctx.fillStyle = color;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    const chars = Array.from(text);
    const widths = chars.map(ch => ctx.measureText(ch).width);
    const total = widths.reduce((a, b) => a + b, 0);
    const span = total / radius;
    let angle = centerAngle - (span / 2) * (clockwise > 0 ? 1 : -1);
    const C = ctx.canvas.width / 2;
    for (let i = 0; i < chars.length; i++) {
      const w = widths[i];
      const a = angle + (clockwise > 0 ? 1 : -1) * (w / 2) / radius;
      ctx.save();
      ctx.translate(C + radius * Math.cos(a), C + radius * Math.sin(a));
      const rot = Math.sin(a) > 0 ? a - Math.PI / 2 : a + Math.PI / 2;
      ctx.rotate(rot);
      ctx.fillText(chars[i], 0, 0);
      ctx.restore();
      angle += (clockwise > 0 ? 1 : -1) * w / radius;
    }
    ctx.restore();
  }

  function drawStar(ctx, cx, cy, r, points, color) {
    ctx.save();
    ctx.fillStyle = color;
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
      const rr = (i % 2 === 0) ? r : r * 0.42;
      const a = (Math.PI * i) / points - Math.PI / 2;
      ctx.lineTo(cx + rr * Math.cos(a), cy + rr * Math.sin(a));
    }
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function makeFaceMap(kind, size) {
    const c = document.createElement("canvas");
    c.width = c.height = size;
    const ctx = c.getContext("2d");
    const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size * 0.5);
    g.addColorStop(0, "#5a5a5a");
    g.addColorStop(1, "#3d3d3d");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, size, size);

    ctx.strokeStyle = "#e8e8e8";
    ctx.lineWidth = size * 0.035;
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size * 0.465, 0, Math.PI * 2);
    ctx.stroke();

    ctx.lineWidth = size * 0.014;
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size * 0.385, 0, Math.PI * 2);
    ctx.stroke();

    if (kind === "front") {
      drawArcText(ctx, "WASTED TOKEN MINT", size * 0.415, Math.PI * 1.5, 1,
        "700 " + (size * 0.068) + "px serif", "#f2f2f2");
      drawArcText(ctx, "EST. 2024", size * 0.415, Math.PI * 0.5, -1,
        "400 " + (size * 0.052) + "px serif", "#b8b8b8");

      ctx.fillStyle = "#f8f8f8";
      ctx.font = "bold " + (size * 0.36) + "px serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("WT", size / 2, size * 0.48);
      drawStar(ctx, size / 2, size * 0.72, size * 0.055, 5, "#e0e0e0");
    } else {
      drawArcText(ctx, "PROOF • NON-FUNGIBLE METAL", size * 0.415, Math.PI * 1.5, 1,
        "600 " + (size * 0.052) + "px sans-serif", "#c8c8c8");

      ctx.fillStyle = "#f5f5f5";
      ctx.font = "bold " + (size * 0.30) + "px sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("10,000", size / 2, size * 0.42);
      ctx.font = "bold " + (size * 0.16) + "px sans-serif";
      ctx.fillText("TOKENS", size / 2, size * 0.63);

      ctx.font = "" + (size * 0.06) + "px sans-serif";
      ctx.fillStyle = "#a0a0a0";
      ctx.fillText("WT-2025", size / 2, size * 0.76);
    }

    const id = ctx.getImageData(0, 0, size, size);
    const data = id.data;
    const N = size * size;
    const h = new Float32Array(N);
    const dhdu = new Float32Array(N);
    const dhdv = new Float32Array(N);

    for (let i = 0; i < N; i++) {
      h[i] = (data[i * 4] + data[i * 4 + 1] + data[i * 4 + 2]) / (3 * 255);
    }

    const d = 2 / (size - 1);
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const i = y * size + x;
        const xl = x > 0 ? x - 1 : x;
        const xr = x < size - 1 ? x + 1 : x;
        const yu = y > 0 ? y - 1 : y;
        const yd = y < size - 1 ? y + 1 : y;
        dhdu[i] = (h[y * size + xr] - h[y * size + xl]) / ((xr - xl) * d);
        dhdv[i] = (h[yd * size + x] - h[yu * size + x]) / ((yd - yu) * d);
      }
    }

    function sample(arr, u, v) {
      let x = (u * 0.5 + 0.5) * (size - 1);
      let y = (v * 0.5 + 0.5) * (size - 1);
      let x0 = x | 0;
      let y0 = y | 0;
      if (x0 < 0) x0 = 0;
      if (y0 < 0) y0 = 0;
      let x1 = x0 + 1;
      let y1 = y0 + 1;
      if (x1 >= size) { x1 = size - 1; x0 = size - 1; }
      if (y1 >= size) { y1 = size - 1; y0 = size - 1; }
      const fx = x - x0;
      const fy = y - y0;
      const i00 = y0 * size + x0;
      const i01 = y0 * size + x1;
      const i10 = y1 * size + x0;
      const i11 = y1 * size + x1;
      return (1 - fx) * (1 - fy) * arr[i00] +
             fx * (1 - fy) * arr[i01] +
             (1 - fx) * fy * arr[i10] +
             fx * fy * arr[i11];
    }

    return { S: size, h, dhdu, dhdv, sample };
  }

  /* ---------- Software coin renderer ---------- */
  function CoinRenderer(canvas, options) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d", { alpha: false });
    this.W = canvas.width;
    this.H = canvas.height;
    this.R = options.R || 1;
    this.thick = options.thickness || 0.14;
    this.half = this.thick / 2;
    this.R2 = this.R * this.R;
    this.scale = Math.min(this.W, this.H) * 0.36 / this.R;
    this.cx = this.W / 2;
    this.cy = this.H / 2;

    this.base = options.base;
    this.spec = options.specColor;
    this.amb = options.ambient ?? 0.12;
    this.diffK = options.diffK ?? 0.55;
    this.specK = options.specK ?? 0.85;
    this.shin = options.shininess ?? 95;
    this.rimK = options.rimK ?? 0.28;
    this.edgeN = options.edgeN ?? 110;
    this.edgeAmp = options.edgeAmp ?? 0.10;
    this.relief = options.reliefScale ?? 0.030;

    this.front = options.frontMap || makeFaceMap("front", 512);
    this.back = options.backMap || makeFaceMap("back", 512);

    this.img = this.ctx.createImageData(this.W, this.H);
    this.buf = this.img.data;

    this.lightPos = options.lightPos || [-2.8, -2.2, 3.8];
  }

  CoinRenderer.prototype.render = function (theta, phi) {
    const W = this.W, H = this.H;
    const R = this.R, R2 = this.R2, half = this.half;
    const scale = this.scale, cx = this.cx, cy = this.cy;
    const c = Math.cos(theta), s = Math.sin(theta);
    const cf = Math.cos(phi), sf = Math.sin(phi);

    const r00 = c, r01 = 0, r02 = s;
    const r10 = sf * s, r11 = cf, r12 = -sf * c;
    const r20 = -cf * s, r21 = sf, r22 = cf * c;

    const dx = r20, dy = r21, dz = r22;
    const Abase = dx * dx + dy * dy;
    const invAbase = Abase > 1e-8 ? 1 / (2 * Abase) : 0;

    const [br, bg, bb] = this.base;
    const [sr, sg, sb] = this.spec;
    const amb = this.amb, dk = this.diffK, sk = this.specK;
    const shin = this.shin, rimK = this.rimK;
    const relief = this.relief;
    const edgeN = this.edgeN, edgeAmp = this.edgeAmp;

    const lp = this.lightPos;
    const lx0 = lp[0], ly0 = lp[1], lz0 = lp[2];

    const frontMap = this.front, backMap = this.back;

    for (let py = 0; py < H; py++) {
      const sy = (py - cy) / scale;
      const ox_y = r10 * sy;
      const oy_y = r11 * sy;
      const oz_y = r12 * sy;

      for (let px = 0; px < W; px++) {
        const sx = (px - cx) / scale;
        const ox = r00 * sx + ox_y;
        const oy = oy_y;
        const oz = r02 * sx + oz_y;

        let tBest = -Infinity;
        let hitType = 0;
        let bestX = 0, bestY = 0, bestZ = 0;

        if (Abase > 1e-8) {
          const B = 2 * (ox * dx + oy * dy);
          const C = ox * ox + oy * oy - R2;
          const disc = B * B - 4 * Abase * C;
          if (disc >= 0) {
            const sd = Math.sqrt(disc);
            const t1 = (-B - sd) * invAbase;
            const z1 = oz + dz * t1;
            if (z1 >= -half && z1 <= half && t1 > tBest) {
              tBest = t1; hitType = 2;
              bestX = ox + dx * t1; bestY = oy + dy * t1; bestZ = z1;
            }
            const t2 = (-B + sd) * invAbase;
            const z2 = oz + dz * t2;
            if (z2 >= -half && z2 <= half && t2 > tBest) {
              tBest = t2; hitType = 2;
              bestX = ox + dx * t2; bestY = oy + dy * t2; bestZ = z2;
            }
          }
        }

        if (Math.abs(dz) > 1e-8) {
          const invDz = 1 / dz;
          const tp = (half - oz) * invDz;
          const xp = ox + dx * tp, yp = oy + dy * tp;
          if (xp * xp + yp * yp <= R2 && tp > tBest) {
            tBest = tp; hitType = 1;
            bestX = xp; bestY = yp; bestZ = half;
          }
          const tm = (-half - oz) * invDz;
          const xm = ox + dx * tm, ym = oy + dy * tm;
          if (xm * xm + ym * ym <= R2 && tm > tBest) {
            tBest = tm; hitType = -1;
            bestX = xm; bestY = ym; bestZ = -half;
          }
        }

        const idx = (py * W + px) << 2;

        if (hitType === 0) {
          const ux = (px - cx) / (W / 2);
          const vy = (py - cy) / (H / 2);
          const d = Math.sqrt(ux * ux + vy * vy);
          const bg = 20 + 26 * (1 - Math.min(d, 1));
          this.buf[idx] = bg;
          this.buf[idx + 1] = bg;
          this.buf[idx + 2] = bg + 4;
          this.buf[idx + 3] = 255;
          continue;
        }

        let nx, ny, nz;

        if (hitType === 2) {
          const rr = Math.sqrt(bestX * bestX + bestY * bestY);
          const invR = 1 / rr;
          const cxn = bestX * invR;
          const cyn = bestY * invR;
          const ang = Math.atan2(bestY, bestX);
          const ridge = edgeAmp * Math.sin(edgeN * ang);
          const len = Math.sqrt(cxn * cxn + cyn * cyn + ridge * ridge);
          const nobjx = cxn / len, nobjy = cyn / len, nobjz = ridge / len;
          nx = r00 * nobjx + r01 * nobjy + r02 * nobjz;
          ny = r10 * nobjx + r11 * nobjy + r12 * nobjz;
          nz = r20 * nobjx + r21 * nobjy + r22 * nobjz;
        } else {
          const map = hitType === 1 ? frontMap : backMap;
          const u = bestX / R;
          const v = -bestY / R;
          let dhx = 0, dhy = 0;
          if (u * u + v * v < 1.02) {
            const dhu = map.sample(map.dhdu, u, v);
            const dhv = map.sample(map.dhdv, u, v);
            dhx = dhu * relief;
            dhy = -dhv * relief;
          }
          const len = Math.sqrt(dhx * dhx + dhy * dhy + 1);
          const nobjx = -dhx / len, nobjy = -dhy / len, nobjz = hitType / len;
          nx = r00 * nobjx + r01 * nobjy + r02 * nobjz;
          ny = r10 * nobjx + r11 * nobjy + r12 * nobjz;
          nz = r20 * nobjx + r21 * nobjy + r22 * nobjz;
        }

        const invLen = 1 / Math.sqrt(nx * nx + ny * ny + nz * nz);
        nx *= invLen; ny *= invLen; nz *= invLen;

        const lx = lx0 - sx;
        const ly = ly0 - sy;
        const lz = lz0 - tBest;
        const invL = 1 / Math.sqrt(lx * lx + ly * ly + lz * lz);
        const Lx = lx * invL, Ly = ly * invL, Lz = lz * invL;

        const Hx = Lx, Hy = Ly, Hz = Lz + 1;
        const invH = 1 / Math.sqrt(Hx * Hx + Hy * Hy + Hz * Hz);
        const Hnx = Hx * invH, Hny = Hy * invH, Hnz = Hz * invH;

        const diff = Math.max(0, nx * Lx + ny * Ly + nz * Lz);
        let nh = nx * Hnx + ny * Hny + nz * Hnz;
        if (nh < 0) nh = 0;
        const spec = Math.pow(nh, shin);

        const rim = Math.pow(1 - Math.max(0, nz), 3) * rimK;

        let rr = br * (amb + diff * dk) + sr * (spec * sk + rim);
        let gg = bg * (amb + diff * dk) + sg * (spec * sk + rim);
        let bb2 = bb * (amb + diff * dk) + sb * (spec * sk + rim);

        if (hitType === 2) {
          const ang = Math.atan2(bestY, bestX);
          const reed = 0.82 + 0.18 * Math.sin(edgeN * ang) * Math.sin(edgeN * ang);
          rr *= reed; gg *= reed; bb2 *= reed;
        }

        if (rr > 1) rr = 1; else if (rr < 0) rr = 0;
        if (gg > 1) gg = 1; else if (gg < 0) gg = 0;
        if (bb2 > 1) bb2 = 1; else if (bb2 < 0) bb2 = 0;

        this.buf[idx] = rr * 255;
        this.buf[idx + 1] = gg * 255;
        this.buf[idx + 2] = bb2 * 255;
        this.buf[idx + 3] = 255;
      }
    }

    this.ctx.putImageData(this.img, 0, 0);
  };

  /* ---------- Build scene ---------- */
  const frontMap = makeFaceMap("front", 512);
  const backMap = makeFaceMap("back", 512);

  const heroCanvas = document.getElementById("coin-hero");
  const hero = new CoinRenderer(heroCanvas, {
    R: 1,
    thickness: 0.13,
    base: [0.76, 0.79, 0.82],
    specColor: [1, 1, 1],
    ambient: 0.10,
    diffK: 0.55,
    specK: 0.90,
    shininess: 100,
    edgeN: 120,
    edgeAmp: 0.10,
    reliefScale: 0.030,
    frontMap,
    backMap
  });

  const editionData = [
    { name: "bronze", state: "available", base: [0.55, 0.30, 0.12], spec: [1.0, 0.78, 0.45] },
    { name: "silver", state: "available", base: [0.72, 0.74, 0.77], spec: [1.0, 1.0, 1.0] },
    { name: "gold", state: "sold-out", base: [0.83, 0.68, 0.22], spec: [1.0, 0.95, 0.65] },
    { name: "black", state: "coming-soon", base: [0.07, 0.07, 0.09], spec: [0.55, 0.60, 0.75], ambient: 0.16, diffK: 0.40, specK: 1.05 }
  ];

  const editionTiles = Array.from(document.querySelectorAll(".edition"));
  const editionAngles = [
    { theta: 0.70, phi: 0.70 },
    { theta: 1.95, phi: 0.62 },
    { theta: 3.18, phi: 0.75 },
    { theta: 4.45, phi: 0.58 }
  ];

  editionTiles.forEach((tile, i) => {
    const data = editionData[i];
    const canvas = tile.querySelector(".edition-canvas");
    const renderer = new CoinRenderer(canvas, {
      R: 1, thickness: 0.13,
      base: data.base, specColor: data.spec,
      ambient: data.ambient ?? 0.10,
      diffK: data.diffK ?? 0.55,
